<script lang="ts">
	// The operator privacy notice (ARCHITECTURE.md §12), public: what whoever
	// runs this instance can and cannot see. Generated by the server from its
	// settings; members are shown it before they sign up.
	import { onMount } from 'svelte';
	import { resolve } from '$app/paths';
	import { api, describeError } from '#lib/api.ts';
	import type { PrivacyNotice } from '#lib/types.ts';

	let notice = $state<PrivacyNotice | null>(null);
	let error = $state('');

	onMount(async () => {
		try {
			notice = await api.get<PrivacyNotice>('/v1/privacy-notice');
		} catch (e) {
			error = describeError(e);
		}
	});
</script>

<svelte:head>
	<title>Privacy notice · Faro</title>
</svelte:head>

{#if error}
	<div class="notice error" role="alert"><p>{error}</p></div>
{:else if !notice}
	<p class="muted" role="status">Loading…</p>
{:else}
	<div class="page-head">
		<h1>What {notice.instance_name} can see</h1>
		<p>
			Faro encrypts reports on your computer, to you and your allies only. This notice, generated
			from this instance's settings, says what its operator can and cannot see.
		</p>
	</div>

	<section class="card see">
		<h2>The operator can see</h2>
		<ul>
			{#each notice.operator_can_see as item, i (i)}<li>{item}</li>{/each}
		</ul>
	</section>
	<section class="card cannot">
		<h2>The operator cannot see</h2>
		<ul>
			{#each notice.operator_cannot_see as item, i (i)}<li>{item}</li>{/each}
		</ul>
	</section>
	{#if notice.caveats.length}
		<section class="card">
			<h2>Limits of this protection</h2>
			<ul>
				{#each notice.caveats as item, i (i)}<li>{item}</li>{/each}
			</ul>
		</section>
	{/if}
	<section class="card">
		<h2>How long things are kept</h2>
		<dl class="facts">
			<dt>Activity records</dt>
			<dd>{notice.retention.event_header_days} days</dd>
			<dt>Reports and details</dt>
			<dd>{notice.retention.blob_days} days</dd>
			<dt>Alerts</dt>
			<dd>{notice.retention.alert_days} days</dd>
		</dl>
		<p class="muted small">Members can choose shorter, never longer.</p>
	</section>
{/if}

<p class="muted small">
	Faro is free software. The open-source software it is built on, and its licences:
	<a href={resolve('/licenses')}>Licences</a>.
</p>

<style>
	ul {
		margin: 0;
	}

	li + li {
		margin-top: 0.35rem;
	}

	/* A hairline of colour on the leading edge says which list is which. */
	.see {
		border-left: 2px solid var(--brand);
	}

	.cannot {
		border-left: 2px solid var(--ok);
	}

	/* Retention periods are figures. */
	.facts dd {
		font-family: var(--mono);
		font-size: 0.88rem;
		font-variant-numeric: tabular-nums;
	}
</style>
